        b = mix(b, nr ? vec3(0.36, 0.2, 0.3) : vec3(0.64, 0.38, 0.52), golden * 0.75); // dusk silhouettes (B01)
        b = mix(b, nr ? vec3(0.11, 0.09, 0.19) : vec3(0.16, 0.14, 0.27), night); // night blocks (T08)
